def analyze_sequence(sequence):
    # Get different numerical representations
    values = []
    for emoji in sequence:
        # Unicode codepoint
        unicode_val = ord(emoji)
        # UTF-8 bytes
        utf8_bytes = list(emoji.encode('utf-8'))
        values.append({
            'emoji': emoji,
            'unicode': unicode_val,
            'utf8': utf8_bytes,
            'utf8_sum': sum(utf8_bytes)
        })
    return values

def try_combinations(sequences):
    possible_chars = []

    for seq in sequences:
        values = analyze_sequence(seq)

        # Try different combinations
        for val in values:
            # Direct unicode value
            if 32 <= val['unicode'] <= 126:
                possible_chars.append(chr(val['unicode']))

            # UTF-8 sum
            if 32 <= val['utf8_sum'] <= 126:
                possible_chars.append(chr(val['utf8_sum']))

            # Try each byte from UTF-8
            for byte in val['utf8']:
                if 32 <= byte <= 126:
