#!/usr/bin/env python3

def load_emoji_sequence():
    with open('/home/ctfplayer/ctf_files/emoji.txt', 'r', encoding='utf-8') as f:
        return f.read().strip()

def get_emoji_value(emoji):
    # Get various representations of the emoji
    unicode_val = ord(emoji)
    utf8_bytes = list(emoji.encode('utf-8'))

    # Get first byte of UTF-8 encoding
    first_byte = utf8_bytes[0] if utf8_bytes else 0

    # Get sum of UTF-8 bytes
    byte_sum = sum(utf8_bytes)

    # Get XOR of UTF-8 bytes
    byte_xor = 0
    for byte in utf8_bytes:
        byte_xor ^= byte

    return {
        'unicode': unicode_val,
        'first_byte': first_byte,
        'byte_sum': byte_sum,
        'byte_xor': byte_xor,
        'utf8_bytes': utf8_bytes
    }

def process_emoji_sequence(sequence):
    result = []
    current_value = None
    current_operation = None

    for char in sequence:
        if char in ['➕', '➖', '❌']:
            # Store operation
            current_operation = char
        else:
            values = get_emoji_value(char)

            if current_value is None:
                current_value = values
            else:
                # Apply operation
                if current_operation == '➕':
                    for key in current_value:
                        if isinstance(current_value[key], (int, float)) and isinstance(values[key], (int, float)):
                            result.append(current_value[key] + values[key])
                elif current_operation == '➖':
                    for key in current_value:
                        if isinstance(current_value[key], (int, float)) and isinstance(values[key], (int, float)):
                            result.append(current_value[key] - values[key])
                elif current_operation == '❌':
                    for key in current_value:
                        if isinstance(current_value[key], (int, float)) and isinstance(values[key], (int, float)):
                            result.append(current_value[key] * values[key])

                current_value = values

    return result

def try_decode_ascii(value):
    # Try to decode as ASCII if in printable range
    if 32 <= value <= 126:
        return chr(value)
    return None

def main():
    sequence = load_emoji_sequence()
    results = process_emoji_sequence(sequence)

    print("Analyzing results...")
    potential_flag = []

    for value in results:
        # Try direct ASCII conversion
        char = try_decode_ascii(abs(value))
        if char:
            potential_flag.append(char)

    # Print potential flag characters
    print("Potential flag characters:", ''.join(potential_flag))

    # Try to find csawctf{ pattern
    flag_string = ''.join(potential_flag)
    if 'csawctf{' in flag_string.lower():
