#!/usr/bin/env python3

def process_emoji_sequence(sequence):
    # Map operators to their corresponding operations
    operators = {
        '➕': '+',
        '➖': '-',
        '❌': '*'
    }

    # Convert emoji sequence into numeric values and operators
    values = []
    current_value = 0
    current_operator = '+'

    for char in sequence:
        if char in operators:
            values.append((current_value, current_operator))
            current_operator = operators[char]
            current_value = 0
        else:
            # Use ord() to get Unicode code point
            emoji_value = ord(char)
            current_value = (current_value * 1000 + emoji_value) % 128

    if current_value != 0:
        values.append((current_value, current_operator))

    # Evaluate the expression
    result = []
    running_total = 0

    for value, operator in values:
        if 32 <= value <= 126:  # printable ASCII range
            result.append(chr(value))
        if operator == '+':
            running_total += value
        elif operator == '-':
            running_total -= value
        elif operator == '*':
            running_total *= value
        running_total = running_total % 128
        if 32 <= running_total <= 126:
            result.append(chr(running_total))

    return ''.join(result)

def main():
    # Read the emoji file
    with open('/home/ctfplayer/ctf_files/emoji.txt', 'r', encoding='utf-8') as f:
        sequence = f.read().strip()

    # Process the sequence
    result = process_emoji_sequence(sequence)
    print("Decoded result:", result)

    # Look for flag pattern
    import re
    flag_pattern = re.compile(r'csawctf{[^}]*}', re.IGNORECASE)
    potential_flags = flag_pattern.findall(result)

    if potential_flags:
        print("\nPotential flags found:")
        for flag in potential_flags:
            print(flag)

if __name__ == "__main__":
    main()

